// agenda de exemplo: cada profissional com os serviços da área; histórico pago nos últimos 13 meses, hoje e a semana marcados
function agendaExemplo() {
  const servicos = [['colo', 'Coloração raiz', 90, 180], ['esc', 'Escova', 45, 60], ['corte', 'Corte feminino', 60, 90], ['gel', 'Unha em gel', 120, 150], ['mani', 'Manicure', 45, 40], ['cm', 'Corte masculino', 40, 60], ['barba', 'Barba', 30, 40], ['limp', 'Limpeza de pele', 75, 160], ['peel', 'Peeling', 45, 220], ['dren', 'Drenagem linfática', 60, 130], ['laser', 'Depilação a laser (área)', 30, 120], ['aval', 'Avaliação', 40, 0]].map(([id, nome, min, preco]) => ({ id, nome, min, preco }));
  const deQuem = { e1: ['colo', 'esc', 'corte'], e2: ['esc', 'corte'], e3: ['gel', 'mani'], e4: ['cm', 'barba'], e5: ['limp', 'peel', 'dren'], e6: ['laser', 'aval'] }, casaDe = { e1: 'sav', e2: 'sav', e3: 'lou', e4: 'lou', e5: 'pam', e6: 'pam' };
  const NOM = ['Ana', 'Bruna', 'Camila', 'Daniela', 'Eduarda', 'Fábio', 'Gabriel', 'Heloísa', 'Igor', 'Jéssica', 'Karina', 'Lucas', 'Mariana', 'Natália', 'Otávio', 'Priscila', 'Renan', 'Simone', 'Thiago', 'Vânia', 'Carolina', 'Marta'], SOB = ['Andrade', 'Barros', 'Cardoso', 'Dias', 'Esteves', 'Faria', 'Guimarães', 'Lacerda', 'Moura', 'Nogueira', 'Queiroz', 'Teixeira'];
  const clientesAg = Array.from({ length: 90 }, (_, i) => ({ id: `k${i}`, nome: `${NOM[i % NOM.length]} ${SOB[(i + Math.floor(i / NOM.length) * 5) % 12]}`, tel: `319988${String(20000 + i * 53).slice(-5)}`, un: ['sav', 'lou', 'pam'][i % 3], valor: i % 9 === 4 ? [100, 150, 80, 200][i % 4] : null }));
  let sem = 17; const rnd = () => { sem = (sem * 9301 + 49297) % 233280; return sem / 233280; };
  const agenda = [], hoje = new Date();
  for (let o = -400; o <= 6; o++) {
    const d = new Date(hoje); d.setDate(d.getDate() + o); if (d.getDay() === 0) continue; const data = hojeISO(o);
    Object.keys(deQuem).forEach((pro) => {
      let h = 9 + Math.floor(rnd() * 4) / 2;
      for (let k = 0, n = o > 0 ? 1 + Math.floor(rnd() * 3) : o === 0 ? 3 + Math.floor(rnd() * 2) : 2 + (rnd() < 0.4 ? 1 : 0); k < n && h < 18.5; k++) {
        const qual = deQuem[pro][Math.floor(rnd() * deQuem[pro].length)], sv = servicos.find((y) => y.id === qual), c = clientesAg[Math.floor(rnd() * clientesAg.length)], v = c.valor ?? sv.preco;
        const passou = o < 0 || (o === 0 && h + sv.min / 60 < hoje.getHours() + hoje.getMinutes() / 60), falta = rnd() < (o === 0 ? 0.08 : 0.006);
        agenda.push({ id: `a${o + 400}${pro}${k}`, data, ini: h, un: casaDe[pro], pro, cli: c.id, serv: sv.id, valor: c.valor, st: passou ? (falta ? 'faltou' : 'feito') : rnd() < 0.5 ? 'confirmado' : 'marcado', ...(passou && !falta ? { pago: v, forma: ['PIX', 'PIX', 'Cartão', 'Dinheiro'][Math.floor(rnd() * 4)] } : {}) });
        h += Math.ceil(sv.min / 30) / 2 + (rnd() < 0.35 ? 0.5 : 0) + (o === 0 && rnd() < 0.3 ? 1 / 6 : 0); // alguns horários quebrados (10:10, 14:40...)
      }
    });
  }
  return { servicos, clientesAg, agenda, diaAg: null, res: { modo: 'dia', d: 0, m: 0, a: 0 } };
}
